<?php
namespace Tests\Feature;
use App\Models\{Company,User,Customer,Appointment,ClinicalAttachment as Attachment,ClinicalAudit};
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Http\UploadedFile;
use Illuminate\Support\{Str,Carbon};
use Illuminate\Support\Facades\{Storage,DB};
use Tests\TestCase;
class ClinicalAttachmentTest extends TestCase {
 use RefreshDatabase;
 private Company $company;private User $dentist;private Customer $patient;private Appointment $appointment;
 private const PDF="%PDF-1.4\n1 0 obj\n<< /Type /Catalog >>\nendobj\n%%EOF\n";
 protected function setUp():void{parent::setUp();Storage::fake('clinical_private');$this->company=Company::create(['name'=>'Clínica teste','slug'=>'attachments']);$this->dentist=$this->user('professional');$this->patient=Customer::create(['company_id'=>$this->company->id,'name'=>'Paciente anexos','active'=>true]);$this->appointment=$this->link($this->dentist,$this->patient);$this->actingAs($this->dentist);}
 private function user(string $role,?Company $company=null):User{return User::create(['company_id'=>($company??$this->company)->id,'name'=>'Profissional teste','email'=>Str::uuid().'@example.test','password'=>'OnlyTest-2026','role'=>$role,'active'=>true,'clinical_access'=>true,'professional_registration'=>'CRO-BA 12345']);}
 private function link(User $user,Customer $patient):Appointment{return Appointment::create(['company_id'=>$user->company_id,'professional_id'=>$user->id,'created_by'=>$user->id,'customer_id'=>$patient->id,'client_name'=>$patient->name,'service'=>'Consulta','starts_at'=>'2026-09-01 10:00','ends_at'=>'2026-09-01 10:30','status'=>'completed']);}
 private function form(array $changes=[]):array{return array_replace(['request_id'=>(string)Str::uuid(),'clinical'=>['title'=>'Documento confidencial','description'=>'Descrição clínica privada'],'file'=>UploadedFile::fake()->createWithContent('exame.pdf',self::PDF),'acknowledge'=>'1'],$changes);}
 private function upload():Attachment{$this->post(route('attachments.store',$this->patient->id),$this->form())->assertSessionHasNoErrors();return Attachment::sole();}
 public function test_upload_encryption_download_integrity_and_audits():void{$a=$this->upload();$this->assertSame('application/pdf',$a->mime);$this->assertSame(strlen(self::PDF),$a->bytes);$raw=Storage::disk('clinical_private')->get($a->path);$this->assertStringNotContainsString('%PDF',$raw);$this->assertStringNotContainsString('Documento confidencial',DB::table('clinical_attachments')->value('title'));$this->get(route('attachments.index',$this->patient->id))->assertOk()->assertHeader('Cache-Control','no-store, private')->assertSee('Documento confidencial');$this->get(route('attachments.download',[$this->patient->id,$a->id]))->assertOk()->assertHeader('Content-Disposition','attachment; filename=anexo-'.$a->id.'.pdf')->assertHeader('X-Content-Type-Options','nosniff')->assertHeader('Cache-Control','no-store, private')->assertContent(self::PDF);$this->assertSame(1,ClinicalAudit::where('event','create_attachment')->where('attachment_id',$a->id)->count());$this->assertSame(1,ClinicalAudit::where('event','download_attachment')->where('attachment_id',$a->id)->count());}
 public function test_retry_has_one_file_and_conflicting_retry_is_rejected():void{$id=(string)Str::uuid();$this->post(route('attachments.store',$this->patient->id),$this->form(['request_id'=>$id]))->assertSessionHasNoErrors();$this->post(route('attachments.store',$this->patient->id),$this->form(['request_id'=>$id]))->assertSessionHasNoErrors();$this->assertDatabaseCount('clinical_attachments',1);$this->assertCount(1,Storage::disk('clinical_private')->allFiles());$this->post(route('attachments.store',$this->patient->id),$this->form(['request_id'=>$id,'file'=>UploadedFile::fake()->createWithContent('novo.pdf',self::PDF.'%changed')]))->assertStatus(409);$this->assertCount(1,Storage::disk('clinical_private')->allFiles());}
 public function test_invalid_formats_size_and_acknowledgement_do_not_write_files():void{foreach([UploadedFile::fake()->createWithContent('script.html','<script>alert(1)</script>'),UploadedFile::fake()->createWithContent('exame.php',self::PDF),UploadedFile::fake()->create('large.pdf',2049,'application/pdf')] as $file)$this->post(route('attachments.store',$this->patient->id),$this->form(['file'=>$file]))->assertSessionHasErrors('file');$data=$this->form();unset($data['acknowledge']);$this->post(route('attachments.store',$this->patient->id),$data)->assertSessionHasErrors('acknowledge');$this->assertDatabaseCount('clinical_attachments',0);$this->assertCount(0,Storage::disk('clinical_private')->allFiles());}
 public function test_only_linked_authorized_clinicians_can_read_and_write():void{$a=$this->upload();$otherCompany=Company::create(['name'=>'Outra clínica','slug'=>'attachments-other']);foreach([$this->user('owner'),$this->user('reception'),$this->user('professional'),$this->user('professional',$otherCompany)] as $user){$this->flushSession();$this->actingAs($user);$status=$user->isProfessional()?404:403;$this->get(route('attachments.index',$this->patient->id))->assertStatus($status);$this->get(route('attachments.download',[$this->patient->id,$a->id]))->assertStatus($status);$this->post(route('attachments.store',$this->patient->id),$this->form())->assertStatus($status);}$this->flushSession();$this->actingAs($this->dentist);$this->dentist->update(['clinical_access'=>false]);$this->get(route('attachments.index',$this->patient->id))->assertForbidden();}
 public function test_patient_binding_and_cancellation_prevent_access():void{$a=$this->upload();$other=Customer::create(['company_id'=>$this->company->id,'name'=>'Outro paciente','active'=>true]);$this->link($this->dentist,$other);$this->get(route('attachments.download',[$other->id,$a->id]))->assertNotFound();$this->appointment->update(['status'=>'cancelled']);$this->get(route('attachments.download',[$this->patient->id,$a->id]))->assertNotFound();}
 public function test_disregard_preserves_file_only_author_and_audited_once():void{$a=$this->upload();$peer=$this->user('professional');$this->link($peer,$this->patient);$this->flushSession();$this->actingAs($peer)->get(route('attachments.download',[$this->patient->id,$a->id]))->assertOk();$data=['clinical'=>['reason'=>'Arquivo enviado incorretamente'],'acknowledge'=>'1'];$this->post(route('attachments.disregard',[$this->patient->id,$a->id]),$data)->assertForbidden();$this->flushSession();$this->actingAs($this->dentist);$this->post(route('attachments.disregard',[$this->patient->id,$a->id]),$data)->assertSessionHasNoErrors();$this->post(route('attachments.disregard',[$this->patient->id,$a->id]),$data)->assertSessionHasNoErrors();$this->assertNotNull($a->fresh()->disregarded_at);Storage::disk('clinical_private')->assertExists($a->path);$this->assertSame(1,ClinicalAudit::where('event','disregard_attachment')->count());$this->get(route('attachments.index',$this->patient->id))->assertOk()->assertSee('Arquivo enviado incorretamente');$this->get(route('attachments.download',[$this->patient->id,$a->id]))->assertContent(self::PDF);}
 public function test_archived_patient_is_read_only_and_invalid_file_fails_closed():void{$a=$this->upload();$this->patient->update(['active'=>false]);$this->get(route('attachments.index',$this->patient->id))->assertOk()->assertDontSee('Salvar anexo');$this->post(route('attachments.store',$this->patient->id),$this->form())->assertStatus(422);$this->get(route('attachments.download',[$this->patient->id,$a->id]))->assertOk();Storage::disk('clinical_private')->put($a->path,'invalid encrypted content');$this->get(route('attachments.download',[$this->patient->id,$a->id]))->assertStatus(503);Storage::disk('clinical_private')->delete($a->path);$this->get(route('attachments.download',[$this->patient->id,$a->id]))->assertStatus(410);$this->assertSame(1,ClinicalAudit::where('event','download_attachment')->count());}
 public function test_failed_database_write_cleans_uncommitted_blob():void{Attachment::creating(fn()=>throw new \RuntimeException('Simulated DB failure'));try{$this->post(route('attachments.store',$this->patient->id),$this->form())->assertStatus(500);$this->assertDatabaseCount('clinical_attachments',0);$this->assertCount(0,Storage::disk('clinical_private')->allFiles());}finally{Attachment::flushEventListeners();Attachment::clearBootedModels();}}
 public function test_owner_audit_has_attachment_id_but_not_clinical_content():void{$a=$this->upload();$this->flushSession();$this->actingAs($this->user('owner'))->get(route('clinical.audit'))->assertOk()->assertSee('Anexo registrado')->assertSee('Anexo #'.$a->id)->assertDontSee('Documento confidencial')->assertDontSee('Descrição clínica privada');}
}
